import type { Market } from "@/lib/content";
import worldMap from "@/lib/content/world-map.generated.json";
import { cn } from "@/lib/utils";

const pins = worldMap.pins as Record<string, { x: number; y: number }>;

/**
 * Dotted world map with the studio and its markets joined by stitched arcs.
 * The dots are a static SVG used as a CSS mask, so they take the theme colour.
 * Generated by `npm run map:build`.
 */
export function WorldMap({ markets }: { markets: Market[] }) {
  const placed = markets.filter((market) => pins[market.id]).map((market) => ({ ...market, ...pins[market.id] }));
  const hq = placed.find((market) => market.hq);
  // When two pins sit close together, the northern one carries its label above.
  const labelAbove = (market: (typeof placed)[number]) =>
    placed.some((other) => other.id !== market.id && Math.hypot(other.x - market.x, other.y - market.y) < 5 && other.y > market.y);

  return (
    <div aria-hidden="true" className="relative w-full" style={{ aspectRatio: worldMap.width / worldMap.height }}>
      <div
        className="absolute inset-0 bg-(--ink-muted) opacity-45"
        style={{ maskImage: "url(/world-dots.svg)", maskSize: "100% 100%", WebkitMaskImage: "url(/world-dots.svg)", WebkitMaskSize: "100% 100%" }}
      />
      <svg viewBox={`0 0 ${worldMap.width} ${worldMap.height}`} className="absolute inset-0 size-full overflow-visible" fill="none">
        {hq
          ? placed
              .filter((market) => !market.hq)
              .map((market) => {
                const lift = Math.abs(market.x - hq.x) * 0.28 + 4;
                const midX = (market.x + hq.x) / 2;
                const midY = Math.min(market.y, hq.y) - lift;
                return (
                  <path
                    key={market.id}
                    d={`M${hq.x} ${hq.y}Q${midX} ${midY} ${market.x} ${market.y}`}
                    stroke="var(--accent)"
                    strokeWidth={0.22}
                    strokeDasharray="1.2 0.9"
                    strokeLinecap="round"
                  />
                );
              })
          : null}
      </svg>
      {placed.map((market) => (
        <span
          key={market.id}
          className="absolute -translate-1/2"
          style={{ left: `${(market.x / worldMap.width) * 100}%`, top: `${(market.y / worldMap.height) * 100}%` }}
        >
          <span className={cn("block rotate-45 bg-accent", market.hq ? "size-3.5" : "size-2.5")} />
          <span className="absolute inset-0 animate-ping rounded-full bg-accent opacity-60 motion-reduce:hidden" />
          <span
            className={cn(
              "absolute left-1/2 -translate-x-1/2 font-mono text-[0.6rem] tracking-widest whitespace-nowrap text-strong uppercase",
              labelAbove(market) ? "bottom-full mb-2" : "top-full mt-2",
            )}
          >
            {market.country}
          </span>
        </span>
      ))}
    </div>
  );
}
